import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int length = sc.nextInt();
        String inputStr = sc.next();
        boolean inParentheses = false;
        StringBuilder temp = new StringBuilder();
        int maxOuter = 0;
        int insideWordsCount = 0;
        for (int index = 0; index < length; index++) {
            char ch = inputStr.charAt(index);
            if (ch == '(') {
                if (!inParentheses) {
                    String[] parts = temp.toString().split("_");
                    for (String part : parts) {
                        maxOuter = Math.max(maxOuter, part.length());
                    }
                }
                inParentheses = true;
                temp = new StringBuilder();
            } else if (ch == ')') {
                inParentheses = false;
                String[] insideParts = temp.toString().split("_");
                for (String p : insideParts) {
                    if (!p.isEmpty()) {
                        insideWordsCount++;
                    }
                }
                temp = new StringBuilder();
            } else {
                temp.append(ch);
            }
        }
        String[] remainingOutside = temp.toString().split("_");
        for (String p : remainingOutside) {
            maxOuter = Math.max(maxOuter, p.length());
        }
        System.out.println(maxOuter + " " + insideWordsCount);
    }
}
