#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int length;
    cin >> length;
    string inputStr;
    cin >> inputStr;
    bool inParentheses = false;
    string temp;
    int maxOuter = 0;
    int insideWordsCount = 0;
    for (int index = 0; index < length; index++) {
        char ch = inputStr[index];
        if (ch == '(') {
            if (!inParentheses) {
                stringstream ss(temp);
                string part;
                while (getline(ss, part, '_')) {
                    maxOuter = max(maxOuter, (int)part.length());
                }
            }
            inParentheses = true;
            temp.clear();
        } else if (ch == ')') {
            inParentheses = false;
            stringstream ss(temp);
            string p;
            while (getline(ss, p, '_')) {
                if (!p.empty()) {
                    insideWordsCount++;
                }
            }
            temp.clear();
        } else {
            temp += ch;
        }
    }
    stringstream ss(temp);
    string p;
    while (getline(ss, p, '_')) {
        maxOuter = max(maxOuter, (int)p.length());
    }
    cout << maxOuter << " " << insideWordsCount << "\n";
    return 0;
}
